example.code:
containers:
  - name: api
    image: ghcr.io/acme/api:2.1.0
    envFrom:
      - configMapRef: { name: api-config }
      - secretRef: { name: api-secrets }
    resources:
      requests: { cpu: 100m, memory: 128Mi }
      limits: { memory: 256Mi }
    readinessProbe:
      httpGet: { path: /health, port: 8000 }
    livenessProbe:
      httpGet: { path: /health, port: 8000 }
      initialDelaySeconds: 15
